const pdfjsLib = window.pdfjsLib;
const PDFLib = window.PDFLib;

// A refused or failed operation must stay readable: error notices remain
// until dismissed, confirmations and hints still fade.
function showToast(message, type = 'info', duration = undefined, options = undefined) {
  return showNotification(message, type, type === 'error' ? 0 : duration, options);
}

const PDFJS_STANDARD_FONT_URL = '/tools/vendor/pdf-runtime/standard_fonts/';
const PDFJS_CMAP_URL = '/tools/vendor/pdf-runtime/cmaps/';

function openPdfJsDocument(bytes, options = {}, onProgress = null) {
  const loadingTask = pdfjsLib.getDocument({
    data: asUint8Array(bytes).slice(),
    standardFontDataUrl: PDFJS_STANDARD_FONT_URL,
    cMapUrl: PDFJS_CMAP_URL,
    cMapPacked: true,
    ...options,
  });
  if (typeof onProgress === 'function') loadingTask.onProgress = onProgress;
  return loadingTask.promise;
}
window.__fernworkInteractionDraftMetrics = () => interactionDraftRuntime.metrics();

const PDF_INTERACTION_CANCEL_EVENT = 'oo-pdf-cancel-interaction';
const PDF_CANCEL_DEPENDENT_DRAG_EVENT = 'oo-pdf-cancel-dependent-drag';

function usePdfInteractionCancel(handler) {
  const handlerRef = useRef(handler);
  handlerRef.current = handler;
  useEffect(() => {
    const cancel = () => handlerRef.current?.();
    window.addEventListener(PDF_INTERACTION_CANCEL_EVENT, cancel);
    return () => window.removeEventListener(PDF_INTERACTION_CANCEL_EVENT, cancel);
  }, []);
}

function useActivePdfRectDraft(dragRef, zoom) {
  useLayoutEffect(() => {
    const drag = dragRef.current;
    if (!drag) return;
    const changedZoom = drag.layoutZoom !== zoom;
    drag.layoutZoom = zoom;
    if (changedZoom && drag.reproject) {
      drag.geometryDirty = true;
      drag.inLayoutReprojection = true;
      try { drag.reproject(); } finally { drag.inLayoutReprojection = false; }
    } else if (drag.armed && drag.latest) {
      interactionDraftRuntime.updateRect(drag.id, drag.latest, zoom);
    }
  });
}

function useCancelDependentPdfDrag(dragRef, handler) {
  const handlerRef = useRef(handler);
  handlerRef.current = handler;
  useEffect(() => {
    const cancel = event => {
      if (shouldCancelDependentPdfDrag(dragRef.current, event.detail)) handlerRef.current?.();
    };
    window.addEventListener(PDF_CANCEL_DEPENDENT_DRAG_EVENT, cancel);
    return () => window.removeEventListener(PDF_CANCEL_DEPENDENT_DRAG_EVENT, cancel);
  }, [dragRef]);
}

function releasePdfDragPointer(drag) {
  const surface = drag?.geometrySurface;
  const pointers = surface?.pdfActiveDragPointers;
  if (!(pointers instanceof Set) || !pointers.delete(drag.id)) return false;
  if (!pointers.size) surface.dispatchEvent(new Event('fernwork:pdf-drag-idle'));
  return true;
}

function cancelActivePdfDrag(dragRef, cleanup = null) {
  const drag = dragRef.current;
  if (!drag) return false;
  drag.onCompositionState = null;
  if (drag.longPressTimer) window.clearTimeout(drag.longPressTimer);
  disposePdfDragReprojection(drag);
  if (Number.isFinite(drag.id)) interactionDraftRuntime.end(drag.id, { commit: false });
  drag.cancelled = true;
  const restoredHold = cancelNativeDragComposition(drag);
  if (drag.frame) cancelAnimationFrame(drag.frame);
  endCrossPageElementDrag(drag.sheet);
  releasePdfDragPointer(drag);
  dragRef.current = null;
  cleanup?.(restoredHold);
  return true;
}

function disposeUnmountedPdfDrag(dragRef) {
  const drag = dragRef.current;
  if (!drag) return false;
  drag.reflowQueue?.cancel?.();
  drag.reflowAbort?.abort?.();
  // A replaced hit node cannot receive lostpointercapture. Release its
  // atomic gesture and visual lease before the page can adopt new ink.
  return cancelActivePdfDrag(dragRef);
}

function useCancelPdfDragOnUnmount(dragRef) {
  useEffect(() => () => disposeUnmountedPdfDrag(dragRef), []);
}

