const PDF_OPT_PROFILES = {
  vector: { label: 'Lossless', dpi: 0, quality: 1, stripMeta: false, keepVector: true },
  images: { label: 'Images only', dpi: 150, quality: 0.78, stripMeta: false, keepVector: true, imageOnly: true },
  quality: { label: 'Raster copy · 220 dpi', dpi: 220, quality: 0.9, stripMeta: false, keepVector: false },
  balanced: { label: 'Raster copy · 150 dpi', dpi: 150, quality: 0.74, stripMeta: true, keepVector: false },
  small: { label: 'Raster copy · 105 dpi', dpi: 105, quality: 0.56, stripMeta: true, keepVector: false },
};

// Download names say which profile produced a file, so comparing profiles
// never overwrites an earlier result: -lossless, -images150, -raster150.
function optimizedPdfSuffix(profileId, imageOptions = {}) {
  const profile = PDF_OPT_PROFILES[profileId] || PDF_OPT_PROFILES.vector;
  if (profile.imageOnly) return `images${Number(imageOptions.dpi) || profile.dpi}`;
  return profile.keepVector ? 'lossless' : `raster${profile.dpi}`;
}

