          fontStyle: annotation.fontStyle || 'normal',
          fontOverride: annotation.fontKey !== previous?.fontKey || annotation.fontWeight !== previous?.fontWeight || annotation.fontStyle !== previous?.fontStyle || annotation.fontResourceHash !== previous?.fontResourceHash,
