        const testDelay = Number(typeof window !== 'undefined' ? window.__fernworkPdfRenderPreviewDelayMs : 0);
        if (testDelay > 0) {
          await new Promise(resolve => window.setTimeout(resolve, clamp(testDelay, 0, 5000)));
        }
