        activeRuntime?.pendingObjectEdits?.size ||
        activeRuntime?.pendingCommits?.size ||
        activeRuntime?.gestureCommits?.size ||
        activeRuntime?.pendingUiPersistence?.size ||
        activeRuntime?.uiDraftTargets?.size
