    if (safety.mutationBlocked && options.internal !== true) {
      if (safety.opening || safety.pageStructureBusy) {
        const runtime = livePdfRuntimeRef.current;
        const readiness = safety.opening
          ? runtime?.readyPromise
          : waitForLivePageStructureIdle(runtime);
        void Promise.resolve(readiness).then(() => {
          updateDoc(docId, updater, options);
        }).catch(error => {
          showToast(userFacingError(error, 'The queued PDF change could not be applied.'), 'error');
        });
        return true;
      }
      const runtime = livePdfRuntimeRef.current;
      const now = Date.now();
      if (!runtime?.lastMutationBlockedToastAt || now - runtime.lastMutationBlockedToastAt > 1_000) {
        if (runtime) runtime.lastMutationBlockedToastAt = now;
        showToast(safety.reason, 'warning');
      }
      return false;
    }
