            targetSourceX: firstFinite(previous.liveCommitted?.x, nextEdit.sourceX),
            targetSourceY: firstFinite(previous.liveCommitted?.y, nextEdit.sourceY),
            targetSourceW: firstFinite(previous.liveCommitted?.w, nextEdit.sourceW),
            targetSourceH: firstFinite(previous.liveCommitted?.h, nextEdit.sourceH),
