      originalText: current.originalText ?? item.str,
      currentText: nextText,
      fontFamily: current.fontFamily || item.fontFamily,
      fontWeight: current.fontWeight || item.fontWeight || '400',
      fontStyle: current.fontStyle || item.fontStyle || 'normal',
      sourceFontName: current.sourceFontName || item.sourceFontName || '',
      embeddedFontFamily: current.embeddedFontFamily || item.embeddedFontFamily || '',
      pdfFontName: current.pdfFontName || item.pdfFontName || '',
      sourceBackground: current.sourceBackground || sourceBackground || appearance.sourceBackground || '',
      color: current.color || appearance.color || '#111111',
      sourceCoverDataUrl: current.sourceCoverDataUrl || appearance.sourceCoverDataUrl || '',
      sourceCoverX: current.sourceCoverX ?? appearance.sourceCoverX,
      sourceCoverY: current.sourceCoverY ?? appearance.sourceCoverY,
      sourceCoverW: current.sourceCoverW ?? appearance.sourceCoverW,
      sourceCoverH: current.sourceCoverH ?? appearance.sourceCoverH,
      sourceCoverSourceX: current.sourceCoverSourceX ?? appearance.sourceCoverSourceX ?? sourceCoverSourceX,
      sourceCoverSourceY: current.sourceCoverSourceY ?? appearance.sourceCoverSourceY ?? sourceCoverSourceY,
      sourceCoverSourceW: current.sourceCoverSourceW ?? appearance.sourceCoverSourceW ?? sourceCoverSourceW,
      sourceCoverSourceH: current.sourceCoverSourceH ?? appearance.sourceCoverSourceH ?? sourceCoverSourceH,
      targetSourceX: nextSourceRect.x,
      targetSourceY: nextSourceRect.y,
      targetSourceW: nextSourceRect.w,
      targetSourceH: nextSourceRect.h,
      targetSourceBaselineX: nextSourceBaseline.x,
      targetSourceBaselineY: nextSourceBaseline.y,
      inlineSize: current.inlineSize,
      blockSize: current.blockSize,
      sourceInlineSize: current.sourceInlineSize,
      sourceBlockSize: current.sourceBlockSize,
      sampleSource: appearance.sampleSource || current.sampleSource || '',
      captureScale: appearance.captureScale || current.captureScale || 0,
      sampleZoom: appearance.sampleZoom || current.sampleZoom || 0,
      sampleRenderScale: appearance.sampleRenderScale || current.sampleRenderScale || 0,
      snapshotOffsetX: current.snapshotOffsetX ?? appearance.snapshotOffsetX,
      snapshotOffsetY: current.snapshotOffsetY ?? appearance.snapshotOffsetY,
      snapshotW: current.snapshotW ?? appearance.snapshotW,
      snapshotH: current.snapshotH ?? appearance.snapshotH,
      dataUrl: preserveSource ? (appearance.glyphDataUrl || current.dataUrl || onCapture?.(item) || '') : current.dataUrl,
