      startY: predicted.y,
      pageId: predicted.pageId || page.id,
      item: predicted,
      appearance,
      snapshot,
      cycleSelectedOnTap: selected && event.pointerType !== 'touch' &&
        !event.shiftKey && !event.ctrlKey && !event.metaKey,
      selectionPayload: payload,
      elementSelector: '.oo-pdf-textbox',
      requiresLongPress: event.pointerType === 'touch' && coversMostOfPage(current, page),
