        drag.appearance = nativeAppearance;
        drag.nativeAppearance = nativeAppearance;
        drag.snapshot = nativeAppearance.previewKind === 'raster' ? nativeAppearance.glyphDataUrl : '';
        if (drag.armed) setDragAppearance(nativeAppearance);
