  useCancelDependentPdfDrag(dragRef, cancelImageRegionInteraction);
  const current = draftEdit || {
    ...(edit || initialPdfImageEdit(page, item, itemId)),
    ...imagePreferencePatch(preferences),
  };
  const displayQuad = Array.isArray(current.quad) && current.quad.length === 4
    ? current.quad
    : Array.isArray(item.quad) && item.quad.length === 4
      ? item.quad
    : displayQuadFromSourceQuad(page, item.sourceQuad || current.sourceQuad || []) || [];
