    type: 'imageRegion',
    sourceId: itemId,
    pageId,
    sourcePageId: page.id,
    rect: { x: itemPatch.x ?? current.x, y: itemPatch.y ?? current.y, w: itemPatch.w ?? current.w, h: itemPatch.h ?? current.h },
    item: { ...item, sourcePageId: page.id },
    edit: edit ? { ...current, ...itemPatch } : undefined,
