          const canonicalRichTextDocument = layer.type === 'text'
            ? richTextDocumentForVerifiedFrame(propertyItem)
            : null;
          const legacyAutofit = layer.type === 'text' && isLegacyTextAutofitFrame(propertyItem);
          const legacyAutofitMaterialization = legacyAutofit
            ? materializeLegacyTextAutofitForResize(propertyItem, propertyItem)
            : null;
          const richTextDocument = legacyAutofitMaterialization?.richTextDocument || canonicalRichTextDocument;
          const legacyAutofitInvalid = legacyAutofit && !legacyAutofitMaterialization;
